use super::*;
#[path="../../mbse-exchange/tests/support/admission_source.rs"]mod fixture;
use mbse_model::{stage1::*,native_views::{self as views,Views},types};
const NATIVE:&[u8]=include_bytes!("../../../docs/parity/p38b/verification/native-01/cold-run/project-set-target-cold-copy.kernspan");
const VIEWS:&[u8]=include_bytes!("../../../docs/parity/p38b/verification/native-01/cold-run/project-set-target-cold-copy.mbse-views.json");
fn setup()->(tempfile::TempDir,Workspace,egui::Context){let area=tempfile::tempdir_in(std::env::var_os("TMPDIR").unwrap()).unwrap();let root=area.path().join("source");std::fs::create_dir(&root).unwrap();let path=fixture::prepare(&root,fixture::XML.as_bytes());let source=Arc::new(ProjectSet::open(&path).unwrap());let mut session=Session::new(area.path()).unwrap();let value:serde_json::Value=serde_json::from_slice(NATIVE).unwrap();session.editor=Editor::new(serde_json::from_value(value["snapshot"].clone()).unwrap(),session.editor.freshness().instance_id).unwrap();let ctx=egui::Context::default();let mut app=Workspace::new(session,None,None,craft_window::Choice::probe(craft_window::Prefix::new("MBSE_CRAFT")),&ctx);let mut doc:views::Document=serde_json::from_slice(VIEWS).unwrap();doc.profile=views::scenarios::RECOVERY_PROFILE.into();doc.binding=None;app.views.active=*doc.views.keys().next().unwrap();app.views.views=Views::restore(&doc.encoded().unwrap(),&app.session.editor).unwrap();app.open_source_import(crate::project_set_ui::ImportRequest{source,member:"supplier".into()});(area,app,ctx)}
fn render(app:&mut Workspace,ctx:&egui::Context,events:Vec<egui::Event>)->Vec<String>{app.audit.clear();let out=ctx.run_ui(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(2200.,1600.))),focused:true,events,..Default::default()},|_|app.source_import_dialog(ctx));let copies=out.platform_output.commands.iter().filter_map(|c|if let egui::OutputCommand::CopyText(s)=c{Some(s.clone())}else{None}).collect();out.drop_without_applying_deltas();copies}
fn settle(app:&mut Workspace,ctx:&egui::Context){for _ in 0..4{render(app,ctx,vec![]);}}
fn wait(app:&mut Workspace,ctx:&egui::Context){for _ in 0..300{settle(app,ctx);if !app.source_import.pending(){return;}std::thread::sleep(std::time::Duration::from_millis(5));}panic!("source worker timeout");}
fn point(app:&mut Workspace,ctx:&egui::Context,key:&str)->egui::Pos2{settle(app,ctx);let mut r=app.audit[key];for _ in 0..32{if r[2]-r[0]>5.&&r[3]-r[1]>=12.&&r[1]>=0.&&r[3]<=1600.{break;}let delta=if r[1]<60.{320.}else{-320.};render(app,ctx,vec![egui::Event::PointerMoved(egui::pos2(((r[0]+r[2])/2.).clamp(50.,2100.),650.)),egui::Event::MouseWheel{unit:egui::MouseWheelUnit::Point,delta:egui::vec2(0.,delta),modifiers:egui::Modifiers::NONE,phase:egui::TouchPhase::Move}]);settle(app,ctx);r=app.audit[key];}assert!(r[2]-r[0]>5.&&r[3]-r[1]>=12.,"clipped{key}");egui::pos2((r[0]+r[2])/2.,(r[1]+r[3])/2.)}
fn button(app:&mut Workspace,ctx:&egui::Context,p:egui::Pos2,pressed:bool)->Vec<String>{render(app,ctx,vec![egui::Event::PointerMoved(p),egui::Event::PointerButton{pos:p,button:egui::PointerButton::Primary,pressed,modifiers:egui::Modifiers::NONE}])}
fn click(app:&mut Workspace,ctx:&egui::Context,key:&str)->Vec<String>{let p=point(app,ctx,key);let mut out=button(app,ctx,p,true);out.extend(button(app,ctx,p,false));settle(app,ctx);out}
fn fill(app:&mut Workspace,ctx:&egui::Context,key:&str,text:&str){click(app,ctx,key);render(app,ctx,vec![egui::Event::Key{key:egui::Key::A,physical_key:None,pressed:true,repeat:false,modifiers:egui::Modifiers{ctrl:true,command:true,..Default::default()}},egui::Event::Text(text.into())]);settle(app,ctx);}
fn prepare(app:&mut Workspace,ctx:&egui::Context){click(app,ctx,"import:system:60082");click(app,ctx,"import:Prepare");wait(app,ctx);assert!(app.source_import.prepared.as_ref().unwrap().summary().ready_for_review,"{}",app.source_import.note);}
fn acknowledge(app:&mut Workspace,ctx:&egui::Context){let codes=app.source_import.prepared.as_ref().unwrap().summary().required_acknowledgements.clone();for code in codes{click(app,ctx,&format!("import:ack:{code}"));}}
fn checked(app:&Workspace)->source::Checked{let p=app.source_import.prepared.as_ref().unwrap();p.review(&p.summary().required_acknowledgements).unwrap().check_source().unwrap()}
#[test]
fn rendered_source_import_prepare_review_copy_apply_and_explicit_undo_redo_use_one_native_history_without_presentation_or_prior_data_changes(){
 let(_a,mut app,ctx)=setup();let before=app.session.editor.snapshot.clone();let old_views=app.views.views.document().clone();prepare(&mut app,&ctx);assert_eq!(app.session.editor.snapshot,before);click(&mut app,&ctx,"import:Apply");assert!(!app.source_import.pending());assert_eq!(app.session.editor.snapshot,before);let copies=click(&mut app,&ctx,"import:Copy");assert_eq!(copies.len(),1);let copy:serde_json::Value=serde_json::from_str(&copies[0]).unwrap();assert_eq!(copy["system"],60082);assert_eq!(copy["mappings"].as_array().unwrap().len(),6);acknowledge(&mut app,&ctx);click(&mut app,&ctx,"import:Apply");wait(&mut app,&ctx);assert!(app.source_import.applied.is_some(),"{}",app.source_import.note);assert_eq!(app.session.editor.snapshot.records,before.records);assert_eq!(app.session.editor.snapshot.drafts,before.drafts);assert_eq!(app.session.editor.snapshot.creation_drafts,before.creation_drafts);assert_eq!(app.session.editor.snapshot.raw_version,before.raw_version);assert_eq!(app.session.editor.snapshot.next_id,before.next_id+4);assert_eq!(app.session.editor.snapshot.model_revision,before.model_revision+1);assert_eq!(app.views.views.document(),&old_views);let admitted=types::load(&app.session.editor.snapshot).unwrap();click(&mut app,&ctx,"import:Undo");assert_eq!(types::load(&app.session.editor.snapshot).unwrap(),types::load(&before).unwrap());assert_eq!(app.session.editor.snapshot.next_id,before.next_id+4);assert!(!app.session.editor.can_undo());click(&mut app,&ctx,"import:Redo");assert_eq!(types::load(&app.session.editor.snapshot).unwrap(),admitted);assert_eq!(app.views.views.document(),&old_views);assert!(!app.source_import_audit()["applied_current"].as_bool().unwrap());
}
#[test]
fn rendered_source_import_queued_cancel_release_precedes_already_ready_checked_publication_and_keeps_sources_and_target_untouched(){
 let(area,mut app,ctx)=setup();prepare(&mut app,&ctx);let before=app.session.editor.snapshot.clone();let c=checked(&app);let(tx,rx)=mpsc::channel();app.source_import.pending=Some(Pending{receiver:rx,cancelled:false});let p=point(&mut app,&ctx,"import:Cancel");button(&mut app,&ctx,p,true);assert!(tx.send(Ok(Completion::Checked(c))).is_ok());button(&mut app,&ctx,p,false);assert_eq!(app.session.editor.snapshot,before);assert!(!app.source_import.open&&!app.source_import.pending());assert!(app.source_import.prepared.is_none()&&app.source_import.applied.is_none());assert_eq!(std::fs::read(area.path().join("source/source.xmi")).unwrap(),fixture::XML.as_bytes());
}
#[test]
fn rendered_source_import_close_while_check_pending_discards_late_authority_and_cold_or_native_replacement_has_no_review_token(){
 let(_a,mut app,ctx)=setup();prepare(&mut app,&ctx);let before=app.session.editor.snapshot.clone();let c=checked(&app);let(tx,rx)=mpsc::channel();app.source_import.pending=Some(Pending{receiver:rx,cancelled:false});click(&mut app,&ctx,"import:Close");assert!(!app.source_import.open&&app.source_import.pending());assert!(tx.send(Ok(Completion::Checked(c))).is_ok());wait(&mut app,&ctx);assert_eq!(app.session.editor.snapshot,before);assert!(app.source_import.applied.is_none());app.reset_type_context();assert!(app.source_import.prepared.is_none()&&app.source_import.acknowledgements.is_empty()&&!app.source_import.pending());assert!(Panel::default().prepared.is_none());
}
#[test]
fn rendered_source_import_raw_scope_and_native_changes_stale_the_old_mapping_without_replacing_filter_text_or_native_work(){
 let(_a,mut app,ctx)=setup();prepare(&mut app,&ctx);acknowledge(&mut app,&ctx);let old=serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap();fill(&mut app,&ctx,"import:system","01");click(&mut app,&ctx,"import:Apply");assert_eq!(app.source_import.system,"01");assert!(!app.source_import.pending());assert!(!app.source_import_audit()["target_current"].as_bool().unwrap());assert_eq!(serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap(),old);click(&mut app,&ctx,"import:system:60082");app.session.editor.command(&app.session.editor.freshness(),Command::EditText{key:RawKey{record:RecordId(1003),field:"criterion".into(),item:None},text:"9e-".into()}).unwrap();let before=app.session.editor.snapshot.clone();click(&mut app,&ctx,"import:Apply");assert!(!app.source_import.pending());assert_eq!(app.session.editor.snapshot,before);assert!(!app.source_import_audit()["target_current"].as_bool().unwrap());
}
#[test]
fn rendered_source_import_changed_original_files_refuse_checked_apply_and_retain_review_and_exact_native_state(){
 let(area,mut app,ctx)=setup();prepare(&mut app,&ctx);acknowledge(&mut app,&ctx);let before=app.session.editor.snapshot.clone();let old=serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap();let path=area.path().join("source/source.xmi");let mut bytes=std::fs::read(&path).unwrap();bytes.push(b' ');std::fs::write(path,bytes).unwrap();click(&mut app,&ctx,"import:Apply");wait(&mut app,&ctx);assert!(app.source_import.error&&app.source_import.note.contains("SOURCE_CHANGED"));assert_eq!(app.session.editor.snapshot,before);assert_eq!(serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap(),old);assert!(app.source_import.applied.is_none());
}
#[test]
fn rendered_source_import_busy_or_new_raw_state_discards_completed_check_without_clearing_owned_native_io_or_drafts(){
 for busy in[false,true]{let(_a,mut app,ctx)=setup();prepare(&mut app,&ctx);let c=checked(&app);if busy{let _job=app.session.begin_recovery().unwrap();}else{app.session.editor.command(&app.session.editor.freshness(),Command::EditText{key:RawKey{record:RecordId(1003),field:"criterion".into(),item:None},text:"9e-".into()}).unwrap();}let before=app.session.editor.snapshot.clone();let(tx,rx)=mpsc::channel();app.source_import.pending=Some(Pending{receiver:rx,cancelled:false});assert!(tx.send(Ok(Completion::Checked(c))).is_ok());settle(&mut app,&ctx);assert_eq!(app.session.editor.snapshot,before);assert_eq!(app.session.pending(),busy);assert!(app.source_import.applied.is_none()&&app.source_import.error);}
}
#[test]
fn source_import_shared_shortcuts_and_window_reopen_preserve_target_and_review_while_native_reset_clears_authority(){
 let(area,mut app,ctx)=setup();prepare(&mut app,&ctx);acknowledge(&mut app,&ctx);let old=serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap();let request=crate::project_set_ui::ImportRequest{source:app.source_import.source.clone().unwrap(),member:"supplier".into()};let before=app.session.editor.snapshot.clone();app.save_path=area.path().join("must-not-save.kernspan").display().to_string();let modifiers=egui::Modifiers::COMMAND;ctx.run_ui(egui::RawInput{events:vec![egui::Event::ModifiersChanged(modifiers),egui::Event::Key{key:egui::Key::Z,physical_key:None,pressed:true,repeat:false,modifiers},egui::Event::Key{key:egui::Key::S,physical_key:None,pressed:true,repeat:false,modifiers}],..Default::default()},|ui|app.handle_shortcuts(ui.ctx())).drop_without_applying_deltas();assert_eq!(app.session.editor.snapshot,before);assert!(!app.session.pending()&&!area.path().join("must-not-save.kernspan").exists());click(&mut app,&ctx,"import:Close");app.open_source_import(request);settle(&mut app,&ctx);assert_eq!(serde_json::to_value(app.source_import.prepared.as_ref().unwrap().summary()).unwrap(),old);assert_eq!(app.source_import.acknowledgements,app.source_import.prepared.as_ref().unwrap().summary().required_acknowledgements);app.reset_type_context();assert!(app.source_import.prepared.is_none()&&app.source_import.applied.is_none()&&app.source_import.acknowledgements.is_empty());
}
#[test]
fn source_import_application_close_cancels_checked_publication_before_saved_or_recovery_close_decision(){
 let(_a,mut app,ctx)=setup();prepare(&mut app,&ctx);let checked=checked(&app);let before=app.session.editor.snapshot.clone();let(tx,rx)=mpsc::channel();app.source_import.pending=Some(Pending{receiver:rx,cancelled:false});assert!(tx.send(Ok(Completion::Checked(checked))).is_ok());app.source_import_request_close();settle(&mut app,&ctx);assert!(!app.source_import.pending()&&!app.source_import.open);assert_eq!(app.session.editor.snapshot,before);assert!(app.source_import.applied.is_none());
}
